	if flag := cmd.InheritedFlags().Lookup("json"); flag != nil && flag.Changed {
		return true
	}
	for _, arg := range cmd.Flags().Args() {
		if arg == "--json" {
			return true
		}
		if strings.HasPrefix(arg, "--json=") {
			value := strings.TrimPrefix(arg, "--json=")
			return value == "" || value == "true" || value == "1"
		}
	}
	return false
}

